import{_ as a,C as s,c as o,o as r,ag as i,j as n,G as l}from"./chunks/framework.Bw-5EFTY.js";const v=JSON.parse('{"title":"Visits","description":"","frontmatter":{},"headers":[],"relativePath":"guide/admin-portal/managing-visits.md","filePath":"guide/admin-portal/managing-visits.md","lastUpdated":1755579203000}'),c={name:"guide/admin-portal/managing-visits.md"};function d(h,e,g,f,u,p){const t=s("ZoomableImage");return r(),o("div",null,[e[0]||(e[0]=i('<h1 id="visits" tabindex="-1">Visits <a class="header-anchor" href="#visits" aria-label="Permalink to &quot;Visits&quot;">​</a></h1><p>The Visits page is your central hub for monitoring all incoming affiliate traffic in real-time. It provides a granular, click-by-click log of every visitor who arrives on your site via a referral link. By analyzing this data, you can gain critical insights into your affiliates&#39; promotional strategies, understand traffic quality, and pinpoint exactly which campaigns are driving the most engagement.</p><h3 id="accessing-the-visits-page" tabindex="-1">Accessing the Visits Page <a class="header-anchor" href="#accessing-the-visits-page" aria-label="Permalink to &quot;Accessing the Visits Page&quot;">​</a></h3><p>To access this section, navigate from your WordPress dashboard to <strong>FluentAffiliate → Visits</strong>.</p><h3 id="features-of-the-visits-page" tabindex="-1">Features of the Visits Page <a class="header-anchor" href="#features-of-the-visits-page" aria-label="Permalink to &quot;Features of the Visits Page&quot;">​</a></h3><p>The main Visits page is composed of powerful filtering tools and a detailed data table to give you a complete picture of your affiliate traffic.</p>',6)),n("p",null,[l(t,{src:"/guide/public/images/admin-portal/visits/visits-dashboard.png",alt:"Visit Dashboard"})]),e[1]||(e[1]=i('<h4 id="filtering-your-traffic-data" tabindex="-1">Filtering Your Traffic Data <a class="header-anchor" href="#filtering-your-traffic-data" aria-label="Permalink to &quot;Filtering Your Traffic Data&quot;">​</a></h4><p>When you have a lot of traffic, finding the information you need is key. Use the filters at the top of the page to sort your data:</p><ul><li><strong>All:</strong> This is the default view, showing an unfiltered list of every single visit recorded by the system.</li><li><strong>Converted:</strong> Select this filter to see only the high-value clicks that led to a successful sale or action.</li><li><strong>Not Converted:</strong> This filter shows you all the clicks that did not lead to a sale.</li><li><strong>Search:</strong> For more specific queries, you can use the search icon on the right to find visits based on keywords.</li></ul><h4 id="understanding-the-visits-table" tabindex="-1">Understanding the Visits Table <a class="header-anchor" href="#understanding-the-visits-table" aria-label="Permalink to &quot;Understanding the Visits Table&quot;">​</a></h4><p>Each row in the table represents a single click and is organized into columns that provide specific details about the visit.</p><ul><li><strong>URL:</strong> This shows the exact destination page on your site where the visitor was sent. For example, this could be a specific product page, a blog post, or a dedicated landing page.</li><li><strong>Referrer:</strong> This column identifies the source of the click—the specific page where the visitor clicked the affiliate link. This is useful for understanding where your traffic is coming from, for instance, a blog review or a social media post.</li><li><strong>Related Referral:</strong> For visits that successfully converted, this column provides a direct link to the corresponding entry in the Referrals log. This allows you to quickly cross-reference a successful click with the commission it generated.</li><li><strong>Affiliate:</strong> Displays the name of the affiliate whose unique link was used for the visit, making it easy to attribute traffic.</li><li><strong>UTM Campaign, UTM Medium, &amp; UTM Source:</strong> These columns are incredibly powerful for advanced tracking. If your affiliates are using UTM parameters in their links, you will see that data here. <ul><li><strong>Use Case:</strong> You can track the performance of specific marketing efforts, like an &#39;email-newsletter&#39; (<code>UTM Medium</code>) or a &#39;summer-sale&#39; (<code>UTM Campaign</code>), to optimize your marketing strategy.</li></ul></li><li><strong>Date:</strong> This column shows the exact date the visit occurred.</li></ul><p>At the bottom of the table, you will find pagination controls to navigate through all your recorded visits and an option to set how many visits are shown per page.</p>',7))])}const y=a(c,[["render",d]]);export{v as __pageData,y as default};
